import app from 'flarum/forum/app';
import Button from 'flarum/common/components/Button';
import Stream from 'flarum/common/utils/Stream';
import extractText from 'flarum/common/utils/extractText';
import passwordless from '../../common/passwordless';
export { passwordless };

/** O estado do passo do código, guardado na instância do modal. */

/** Espera depois de pedir um código, antes de poder pedir outro. */
const RESEND_DELAY = 30_000;
export function codeLength() {
  return app.forum.attribute('magicLinkCodeLength') || 6;
}
export function createState() {
  return {
    ref: null,
    email: '',
    code: Stream(''),
    honeypot: Stream(''),
    resendAt: 0
  };
}
export function requestCode(state, body, errorHandler) {
  return app.request({
    method: 'POST',
    url: app.forum.attribute('apiUrl') + '/magic-link',
    body: {
      ...body,
      honeypot: state.honeypot()
    },
    errorHandler
  }).then(response => {
    state.ref = response.ref;
    state.code('');
    state.resendAt = Date.now() + RESEND_DELAY;

    // Redesenha quando o "Enviar um novo código" volta a valer.
    setTimeout(() => m.redraw(), RESEND_DELAY + 50);
  });
}
export function verifyCode(state, errorHandler) {
  return app.request({
    method: 'POST',
    url: app.forum.attribute('baseUrl') + '/magic-link/verify',
    body: {
      ref: state.ref,
      code: state.code()
    },
    errorHandler
  });
}

/** Bilhete que o servidor aceita no lugar da senha atual (trocar e-mail, apagar a conta). */
export function reauthTicket(state) {
  return `magic-link:${state.ref}:${state.code().replace(/\D/g, '')}`;
}

/**
 * Campo que só robô preenche. Fica fora da tela, não escondido com display,
 * porque alguns robôs pulam campos invisíveis.
 */
export function honeypotField(state) {
  return m("div", {
    className: "MagicLink-honeypot",
    "aria-hidden": "true"
  }, m("input", {
    type: "text",
    name: "magicLinkWebsite",
    tabindex: -1,
    autocomplete: "off",
    bidi: state.honeypot
  }));
}

/**
 * O passo do código, com as classes de formulário do core: o tema (Avocado,
 * Canela) estiliza os campos como os do login.
 */
export function addCodeFields(items, state, options) {
  const label = extractText(app.translator.trans('ramon-magic-link.forum.code.label'));
  const canResend = Date.now() >= state.resendAt;
  items.add('magicLinkHint', m("p", {
    className: "helpText MagicLink-hint"
  }, app.translator.trans(`ramon-magic-link.forum.code.sent_${options.type}`, {
    email: m("strong", null, state.email)
  })), 40);
  items.add('magicLinkCode', m("div", {
    className: "Form-group MagicLink-codeGroup"
  }, m("label", {
    className: "label",
    for: "magicLinkCode"
  }, label), m("input", {
    id: "magicLinkCode",
    className: "FormControl MagicLink-code",
    name: "code",
    type: "text",
    inputmode: "numeric",
    autocomplete: "one-time-code",
    pattern: "[0-9]*",
    maxlength: codeLength(),
    placeholder: '0'.repeat(codeLength()),
    "aria-label": label,
    bidi: state.code,
    disabled: options.loading
  })), 30);
  items.add('magicLinkActions', m("div", {
    className: "Form-group MagicLink-actions"
  }, m(Button, {
    className: "Button Button--text Button--link",
    type: "button",
    onclick: options.onResend,
    disabled: options.loading || !canResend
  }, app.translator.trans('ramon-magic-link.forum.code.resend_button')), options.onChangeEmail && m(Button, {
    className: "Button Button--text Button--link",
    type: "button",
    onclick: options.onChangeEmail,
    disabled: options.loading
  }, app.translator.trans('ramon-magic-link.forum.code.change_email_link'))), -20);
}
export function submitButton(key, loading) {
  return m("div", {
    className: "Form-group"
  }, m(Button, {
    className: "Button Button--primary Button--block",
    type: "submit",
    loading: loading
  }, app.translator.trans(key)));
}
export function resentAlert() {
  return {
    type: 'success',
    content: app.translator.trans('ramon-magic-link.forum.code.resent_message')
  };
}
flarum.reg.add('ramon-magic-link', 'forum/utils/magicLink', { passwordless: passwordless,codeLength: codeLength,createState: createState,requestCode: requestCode,verifyCode: verifyCode,reauthTicket: reauthTicket,honeypotField: honeypotField,addCodeFields: addCodeFields,submitButton: submitButton,resentAlert: resentAlert, });