import app from 'flarum/forum/app';
import { extend, override } from 'flarum/common/extend';
import { addCodeFields, createState, passwordless, reauthTicket, requestCode, resentAlert, submitButton } from '../utils/magicLink';

/**
 * Trocar o e-mail pede a senha atual. Sem senha, um código vai para o e-mail
 * atual e o bilhete dele segue no lugar da senha (o servidor o confere no
 * password checker da extensão).
 */
export default function extendChangeEmailModal() {
  extend('flarum/forum/components/ChangeEmailModal', 'oninit', function () {
    this.magicLink = createState();
    this.magicLinkSend = resend => {
      this.loading = true;
      this.alertAttrs = null;
      requestCode(this.magicLink, {
        type: 'reauth'
      }, this.onerror.bind(this)).then(() => {
        this.magicLink.email = app.session.user.email() || '';
        this.loading = false;
        if (resend) this.alertAttrs = resentAlert();
        m.redraw.sync();
        this.$('[name=code]').trigger('select');
      }, this.loaded.bind(this));
    };
  });
  extend('flarum/forum/components/ChangeEmailModal', 'fields', function (items) {
    if (!passwordless() || this.success) return;
    items.remove('password');
    if (this.magicLink.ref) {
      addCodeFields(items, this.magicLink, {
        type: 'reauth',
        loading: this.loading,
        onResend: () => this.magicLinkSend(true)
      });
    }
    if (items.has('submit')) {
      items.setContent('submit', submitButton(this.magicLink.ref ? 'ramon-magic-link.forum.change_email.submit_button' : 'ramon-magic-link.forum.change_email.send_code_button', this.loading));
    }
  });
  override('flarum/forum/components/ChangeEmailModal', 'onsubmit', function (original, e) {
    // E-mail igual: o core só fecha o modal.
    if (!passwordless() || this.email() === app.session.user.email()) return original(e);
    e.preventDefault();
    if (!this.magicLink.ref) {
      this.magicLinkSend(false);
      return;
    }
    this.password(reauthTicket(this.magicLink));
    original(e);
  });
  override('flarum/forum/components/ChangeEmailModal', 'onerror', function (original, error) {
    original(error);

    // O 401 aqui é o código, não uma senha.
    if (passwordless() && error.status === 401 && this.alertAttrs) {
      this.alertAttrs.content = app.translator.trans('ramon-magic-link.forum.code.invalid_message');
      m.redraw();
    }
  });
}
flarum.reg.add('ramon-magic-link', 'forum/extenders/extendChangeEmailModal', extendChangeEmailModal);